 RegexpMatchFnName = \"match\"
 RegexpNotMatchFnName = \"not_match\"
 RegexpReplaceFnName = \"replace\"
 maxExpressionDepth = 128
 maxExpressionBytes = 65536
)

type Expression struct { prefix,suffix string; expr Expr }
func (p *Expression) Namespace() string { if v,ok:=p.expr.(VarExpr);ok{return v.Namespace};return \"\" }
func (p *Expression) Name() string { if v,ok:=p.expr.(VarExpr);ok{return v.Name};return \"\" }

// Interpolate evaluates a template and optionally validates every variable.
func (p *Expression) Interpolate(traits map[string][]string, validation ...func(string,string)error)([]string,error){
 if p==nil || p.expr==nil{return nil,trace.BadParameter(\"empty expression\")}
 var validate func(string,string)error
 if len(validation)>0 {validate=validation[0]}
 values,err:=evalStrings(p.expr,EvaluateContext{VarValue:func(v VarExpr)([]string,error){
  if validate"'!=nil {if err:=validate(v.Namespace,v.Name);err!=nil{return nil,trace.Wrap(err)}}
  val,ok:=traits[v.Name];if !ok{return nil,trace.NotFound("variable %q is not found",v.String())}
  return val,nil
 }})
 if err!=nil{return nil,trace.Wrap(err)}
 out:=make([]string,0,len(values));for _,v:=range values {if v!="" {out=append(out,p.prefix+v+p.suffix)}}
 if len(out)==0{return nil,trace.NotFound("variable interpolation result is empty")}
 return out,nil
}

func NewExpression(input string)(*Expression,error){
 prefix,body,suffix,templated,err:=splitTemplate(input);if err!=nil{return nil,err}
 if !templated {return &Expression{expr:VarExpr{Namespace:LiteralNamespace,Name:body}},nil}
 expr,err:=parse(body);if err!=nil{return nil,trace.BadParameter("invalid expression %q: %v",input,err)}
 if expr.Kind()!=reflect.String{return nil,trace.BadParameter("expression %q must evaluate to a string, got %s",input,expr.Kind())}
 if err:=validateExpr(expr);err!=nil{return nil,trace.Wrap(err)}
 return &Expression{prefix:prefix,suffix:suffix,expr:expr},nil
}

func splitTemplate(input string)(prefix,body,suffix string,templated bool,err error){
 s:=strings.TrimSpace(input)
 if !strings.ContainsAny(s,"{}") {return "",s,"",false,nil}
 start:=strings.Index(s,"{{");end:=strings.Index(s,"}}")
 if start<0 || end<start+2 || strings.ContainsAny(s[:start],"{}") || strings.ContainsAny(s[end+2:],"{}") || strings.ContainsAny(s[start+2:end],"{}") {
  return "","","",false,trace.BadParameter("malformed template usage %q: expected one {{expression}}",input)
 }
 return s[:start],strings.TrimSpace(s[start+2:end]),s[end+2:],true,nil
}

func parse(exprStr string)(Expr,error){
 if err:=checkExpressionSize(exprStr);err!=nil{return nil,err}
 p,err:=predicate.NewParser(predicate.Def{Functions:map[string]interface{}{
  "email.local":func(args ...interface{})(interface{},error){if err:=arity("email.local",args,1);err!=nil{return nil,err};in,err:=stringArg("email.local",args[0]);if err!=nil{return nil,err};return EmailLocalExpr{Input:in},nil},
  "regexp.replace":func(args ...interface{})(interface{},error){if err:=arity("regexp.replace",args,3);err!=nil{return nil,err};in,err:=stringArg("regexp.replace",args[0]);if err!=nil{return nil,err};pattern,err:=constantArg("regexp.replace pattern",args[1]);if err!=nil{return nil,err};replacement,err:=constantArg("regexp.replace replacement",args[2]);if err!=nil{return nil,err};re,err:=compileRegexp(pattern);if err!=nil{return nil,err};return RegexpReplaceExpr{Input:in,Pattern:pattern,Replacement:replacement,re:re},nil},
  "regexp.match":func(args ...interface{})(interface{},error){if err:=arity("regexp.match",args,1);err!=nil{return nil,err};pattern,err:=constantArg("regexp.match pattern",args[0]);if err!=nil{return nil,err};re,err:=compileRegexp(pattern);if err!=nil{return nil,err};return RegexpMatchExpr{Pattern:pattern,re:re},nil},
  "regexp.not_match":func(args ...interface{})(interface{},error){if err:=arity("regexp.not_match",args,1);err!=nil{return nil,err};pattern,err:=constantArg("regexp.not_match pattern",args[0]);if err!=nil{return nil,err};re,err:=compileRegexp(pattern);if err!=nil{return nil,err};return RegexpNotMatchExpr{Pattern:pattern,re:re},nil},
 },GetIdentifier:buildVarExpr,GetProperty:buildVarExprFromProperty})
 if err!=nil{return nil,trace.BadParameter("cannot initialize expression parser: %v",err)}
 value,err:=p.Parse(exprStr);if err!=nil{return nil,trace.BadParameter("invalid expression %q: %v",exprStr,err)}
 expr,ok:=value.(Expr);if !ok{return nil,trace.BadParameter("expected variable or function expression in %q",exprStr)}
 return expr,nil
}

func arity(name string,args []interface{},want int)error{if len(args)!=want{return trace.BadParameter("%s expects %d argument(s), got %d",name,want,len(args))};return nil}
func stringArg(name string,v interface{})(Expr,error){if s,ok:=v.(string);ok{return StringLitExpr{Value:s},nil};e,ok:=v.(Expr);if !ok||e.Kind()!=reflect.String{return nil,trace.BadParameter("%s requires a string expression, got %T",name,v)};return e,nil}
func constantArg(name string,v interface{})(string,error){s,ok:=v.(string);if !ok{return "",trace.BadParameter("%s requires a constant string literal, got %T",name,v)};return s,nil}
func buildVarExpr(fields []string)(interface{},error){
 if len(fields)==1 {if fields[0]=="internal"||fields[0]=="external"||fields[0]==LiteralNamespace{return VarExpr{Namespace:fields[0]},nil}}
 if len(fields)!=2{return nil,trace.BadParameter("variable must have exactly two components: namespace.name, got %q",strings.Join(fields,"."))}
 switch fields[0] {case "internal","external",LiteralNamespace: default:return nil,trace.BadParameter("unsupported variable namespace %q",fields[0])}
 if fields[1]==""{return nil,trace.BadParameter("variable name is empty in %q",strings.Join(fields,"."))}
 return VarExpr{Namespace:fields[0],Name:fields[1]},nil
}
func buildVarExprFromProperty(base,key interface{})(interface{},error){
 v,ok:=base.(VarExpr);if !ok||v.Name!=""{return nil,trace.BadParameter("bracket variable must have exactly two components: namespace['"\\\"name\\\"]\")}
 name,ok:=key.(string);if "'!ok{return nil,trace.BadParameter("bracket variable name must be a quoted string")}
 if name==""{return nil,trace.BadParameter("variable name is empty in %q",v.Namespace)}
 return VarExpr{Namespace:v.Namespace,Name:name},nil
}
func validateExpr(expr Expr)error{switch e:=expr.(type){case VarExpr:if e.Name==""{return trace.BadParameter("variable %q is incomplete: expected namespace.name",e.Namespace)};case EmailLocalExpr:return validateExpr(e.Input);case RegexpReplaceExpr:return validateExpr(e.Input)};return nil}
func checkExpressionSize(s string)error{
 if len(s)>maxExpressionBytes{return trace.BadParameter("expression exceeds maximum length")}
 depth:=0;quoted:=byte(0);escaped:=false
 for i:=0;i<len(s);i++{c:=s[i];if quoted!=0 {if escaped{escaped=false;continue};if c==92{escaped=true;continue};if c==quoted{quoted=0};continue};switch c {case 34,39,96:quoted=c;case '"'(', '[':depth++;if depth>maxExpressionDepth{return trace.BadParameter(\"expression exceeds maximum depth\")};case ')',']':depth--}}
 return nil
}

type Matcher interface {Match(string)bool}
type MatcherFn func(string)bool
func (f MatcherFn)Match(s string)bool{return f(s)}
func NewAnyMatcher(inputs []string)(Matcher,error){matchers:=make([]Matcher,0,len(inputs));for _,s:=range inputs{m,err:=NewMatcher(s);if err"'!=nil{return nil,err};matchers=append(matchers,m)};return MatcherFn(func(s string)bool{for _,m:=range matchers{if m.Match(s){return true}};return false}),nil}

type MatchExpression struct {prefix,suffix string; expr Expr}
func (m *MatchExpression)Match(in string)bool{
 if m==nil||m.expr==nil||!strings.HasPrefix(in,m.prefix)||!strings.HasSuffix(in,m.suffix)||len(in)<len(m.prefix)+len(m.suffix){return false}
 middle:=in[len(m.prefix):len(in)-len(m.suffix)]
 value,err:=m.expr.Evaluate(EvaluateContext{MatcherInput:middle});if err!=nil{return false};matched,ok:=value.(bool);return ok&&matched
}
func NewMatcher(input string)(Matcher,error){
 prefix,body,suffix,templated,err:=splitTemplate(input);if err!=nil{return nil,err}
 var expr Expr
 if templated {expr,err=parse(body);if err!=nil{return nil,trace.Wrap(err)};if err=validateExpr(expr);err!=nil{return nil,err}}
 if !templated {
  pattern:=body
  if !strings.HasPrefix(body,"''^")||!strings.HasSuffix(body,"$"){pattern="''^"+utils.GlobToRegexp(body)+"$"}
  re,err:=compileRegexp(pattern);if err!=nil{return nil,err};expr=RegexpMatchExpr{Pattern:pattern,re:re}
 }
 if expr.Kind()!=reflect.Bool{return nil,trace.BadParameter("matcher %q must evaluate to a boolean, got %s",input,expr.Kind())}
 return &MatchExpression{prefix:prefix,suffix:suffix,expr:expr},nil
}
