 middle:=in[len(m.prefix):len(in)-len(m.suffix)]
 value,err:=m.expr.Evaluate(EvaluateContext{MatcherInput:middle});if err!=nil{return false};matched,ok:=value.(bool);return ok&&matched
}
func NewMatcher(input string)(Matcher,error){
