func (p *Expression) Namespace() string {
	if v, ok := p.expr.(VarExpr); ok {
		return v.Namespace
	}
	return ""
}
func (p *Expression) Name() string {
	if v, ok := p.expr.(VarExpr); ok {
		return v.Name
	}
	return ""
}

// Interpolate evaluates a template and optionally validates every variable.
func (p *Expression) Interpolate(traits map[string][]string, validation ...func(string, string) error) ([]string, error) {
	if p == nil || p.expr == nil {
		return nil, trace.BadParameter("empty expression")
	}
	var validate func(string, string) error
	if len(validation) > 0 {
		validate = validation[0]
	}
	values, err := evalStrings(p.expr, EvaluateContext{VarValue: func(v VarExpr) ([]string, error) {
		if validate != nil {
			if err := validate(v.Namespace, v.Name); err != nil {
				return nil, trace.Wrap(err)
			}
		}
		val, ok := traits[v.Name]
		if !ok {
			return nil, trace.NotFound("variable %q is not found", v.String())
		}
		return val, nil
	}})
	if err != nil {
		return nil, trace.Wrap(err)
	}
	out := make([]string, 0, len(values))
	for _, v := range values {
		if v != "" {
			out = append(out, p.prefix+v+p.suffix)
		}
	}
	if len(out) == 0 {
		return nil, trace.NotFound("variable interpolation result is empty")
	}
	return out, nil
}

func NewExpression(input string) (*Expression, error) {
	prefix, body, suffix, templated, err := splitTemplate(input)
	if err != nil {
		return nil, err
	}
	if !templated {
		return &Expression{expr: VarExpr{Namespace: LiteralNamespace, Name: body}}, nil
	}
	expr, err := parse(body)
	if err != nil {
		return nil, trace.BadParameter("invalid expression %q: %v", input, err)
	}
	if expr.Kind() != reflect.String {
		return nil, trace.BadParameter("expression %q must evaluate to a string, got %s", input, expr.Kind())
	}
	if err := validateExpr(expr); err != nil {
		return nil, trace.Wrap(err)
	}
	return &Expression{prefix: prefix, suffix: suffix, expr: expr}, nil
}

func splitTemplate(input string) (prefix, body, suffix string, templated bool, err error) {
	s := strings.TrimSpace(input)
	if !strings.ContainsAny(s, "{}") {
		return "", s, "", false, nil
	}
	start := strings.Index(s, "{{")
	end := strings.Index(s, "}}")
	if start < 0 || end < start+2 || strings.ContainsAny(s[:start], "{}") || strings.ContainsAny(s[end+2:], "{}") || strings.ContainsAny(s[start+2:end], "{}") {
		return "", "", "", false, trace.BadParameter("malformed template usage %q: expected one {{expression}}", input)
	}
	return s[:start], strings.TrimSpace(s[start+2 : end]), s[end+2:], true, nil
}
// EvaluateContext supplies variable values and matcher input.
type EvaluateContext struct {
	VarValue     func(VarExpr) ([]string, error)
	MatcherInput string
}

type StringLitExpr struct{ Value string }

func (e StringLitExpr) String() string                        { return strconv.Quote(e.Value) }
func (StringLitExpr) Kind() reflect.Kind                      { return reflect.String }
func (e StringLitExpr) Evaluate(EvaluateContext) (any, error) { return []string{e.Value}, nil }

type VarExpr struct{ Namespace, Name string }

func (e VarExpr) String() string   { return e.Namespace + "." + e.Name }
func (VarExpr) Kind() reflect.Kind { return reflect.String }
func (e VarExpr) Evaluate(ctx EvaluateContext) (any, error) {
	if e.Namespace == LiteralNamespace {
		return []string{e.Name}, nil
	}
	if ctx.VarValue == nil {
		return nil, trace.BadParameter("no resolver for variable %q", e.String())
	}

